DROP TABLE IF EXISTS T_PROPERTIES;
CREATE TABLE T_PROPERTIES
(
    "ID"        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "KEY"       VARCHAR(255) NOT NULL,
    "VALUE"     VARCHAR(12000),
    "SOURCE"    BIGINT      NOT NULL,
    "ORIGIN"    VARCHAR(1024),
    "IS_ACTIVE" BOOLEAN      NOT NULL
);

DROP INDEX IF EXISTS sd_idx ON system_dict;
DROP INDEX IF EXISTS sd_name_idx ON system_dict;
DROP TABLE IF EXISTS system_dict;
CREATE TABLE system_dict  (
    id BIGINT NOT NULL AUTO_INCREMENT(3004),
    parent_id BIGINT NOT NULL ,
    name varchar(50)  NOT NULL  ,
    sort BIGINT NOT NULL  ,
    status BIGINT NOT NULL
) ;
CREATE INDEX sd_idx ON system_dict(parent_id, name);
CREATE INDEX sd_name_idx ON system_dict(name);

DROP TABLE IF EXISTS system_extra_type;
CREATE TABLE system_extra_type
(
    id   BIGINT     NOT NULL AUTO_INCREMENT(5),
    type varchar(30) NOT NULL,
    val  varchar(30) NOT NULL
);

DROP INDEX IF EXISTS snet_idx ON system_node_extra_type;
DROP TABLE IF EXISTS system_node_extra_type;
CREATE TABLE system_node_extra_type
(
    dict_id       BIGINT NOT NULL,
    extra_type_id BIGINT NOT NULL
);
CREATE INDEX snet_idx ON system_node_extra_type(dict_id, extra_type_id);

DROP INDEX IF EXISTS szet_idx ON system_zone_extra_type;
DROP TABLE IF EXISTS system_zone_extra_type;
CREATE TABLE system_zone_extra_type
(
    dict_id       BIGINT NOT NULL,
    extra_type_id BIGINT NOT NULL
);
CREATE INDEX szet_idx ON system_zone_extra_type(dict_id, extra_type_id);

DROP TABLE IF EXISTS server_metrics;
DROP TABLE IF EXISTS server_ping_log;

DROP INDEX IF EXISTS SI_IDX_SERVER_NAME ON server_info;
DROP TABLE IF EXISTS server_info;
CREATE TABLE server_info  (
  id BIGINT NOT NULL AUTO_INCREMENT,
  cluster_name varchar(100) NOT NULL ,
  server_name varchar(100) NOT NULL ,
  server_host varchar(64) NOT NULL ,
  server_port INT NOT NULL ,
  environment varchar(50) NOT NULL ,
  region varchar(50)  NOT NULL  ,
  type varchar(50)  NOT NULL  ,
  enabled BIGINT NOT NULL DEFAULT 1,
  created_at timestamp NOT NULL DEFAULT current_timestamp()
) ;
CREATE INDEX SI_IDX_CLUSTER_SERVER ON server_info(cluster_name, server_name, type);
CREATE INDEX SI_IDX_type ON server_info(type);

CREATE TABLE server_metrics  (
  id BIGINT NOT NULL AUTO_INCREMENT,
  server_id BIGINT NOT NULL ,
  total_memory BIGINT NOT NULL ,
  used_memory BIGINT NOT NULL ,
  free_memory BIGINT NOT NULL ,
  cpu_usage BIGINT NOT NULL ,
  thread_count BIGINT NOT NULL ,
  deamon_thread_count BIGINT NOT NULL ,
  heap_used BIGINT ,
  heap_max BIGINT,
  status BIGINT NOT NULL DEFAULT 1,
  check_time timestamp NOT NULL DEFAULT current_timestamp()
) ;
CREATE INDEX SM_IDX_SERVER_TIME ON server_metrics(server_id, check_time);

CREATE TABLE server_ping_log  (
     id BIGINT NOT NULL AUTO_INCREMENT,
     server_id BIGINT NOT NULL ,
     latency_ms BIGINT NOT NULL ,
     packet_loss BIGINT DEFAULT 0,
     status BIGINT NOT NULL DEFAULT 1,
     check_time timestamp NOT NULL DEFAULT current_timestamp()
) ;
CREATE INDEX SPL_IDX_SERVER_TIME ON server_ping_log(server_id, check_time);




